INSERT INTO `chatbot_fast_paths` VALUES (1,'general','Profil Kepala Dinas','kepala dinas, siapa kadis, kadis, pimpinan, pimpinan diskominfotik, nama kadis, kadis kominfo, kadis diskominfotik, dilantik, menjabat, lantik, di lantik','Kepala Dinas Komunikasi, Informatika dan Statistik (Diskominfotik) Kota Banda Aceh saat ini dijabat oleh Bapak **Ir. Muhammad Zubir, S.Si.T M.Si**. Ia resmi dilantik sebagai pejabat definitif Kepala Dinas pada Senin, 20 April 2026, setelah sebelumnya sempat menjabat sebagai Pelaksana Tugas (Plt) selama 6 bulan sejak Oktober 2025 lalu.',1,1,'2026-09-04 07:47:12','2026-09-07 04:04:19'),(2,'general','Alamat & Lokasi Kantor','alamat, lokasi, gedung, balai kota, rute, tempat diskominfotik, dimana kantor, dimana diskominfotik, alamat diskominfotik, letak diskominfotik, posisi diskominfotik, arah kantor, lokasi diskominfotik, jalan diskominfotik','Kantor Dinas Komunikasi, Informatika dan Statistik (Diskominfotik) Kota Banda Aceh beralamat di:\n\n**Kompleks Balai Kota Banda Aceh (Gedung C Lantai 3)**\nJl. Tgk. Abu Lam U No. 7, Gampong Kp. Baru, Kec. Baiturrahman, Kota Banda Aceh, Aceh 23116.',1,2,'2026-09-04 07:47:12','2026-09-04 07:47:12'),(3,'general','Kontak Resmi & Website','kontak, email, website, nomor telepon, tlp, no telp, call center, 112, hubungi diskominfotik, nomor diskominfotik','Kontak resmi Dinas Komunikasi, Informatika dan Statistik Kota Banda Aceh:\n\n- **Email Resmi:** diskominfotik@bandaacehkota.go.id\n- **Website Resmi:** https://diskominfotik.bandaacehkota.go.id\n- **Portal Satu Data:** https://data.bandaacehkota.go.id\n- **Call Center Darurat:** 112 (Banda Aceh Siaga)\n- **Lokasi:** Balai Kota Banda Aceh (Gedung C Lantai 3), Jl. Tgk. Abu Lam U No. 7',1,3,'2026-09-04 07:47:12','2026-09-04 07:47:12'),(4,'general','Jam Operasional Kantor','jam kerja, jam operasional, jam buka, jam tutup, jam layanan, hari kerja, jadwal buka, jadwal pelayanan, kapan buka, waktu buka, waktu operasional, buka jam berapa, jam berapa, poh padip, poh padup','Jam operasional pelayanan administrasi dan Front Office Diskominfotik Kota Banda Aceh:\n\n- **Senin - Kamis:** Pukul 08:00 - 16:45 WIB (Istirahat: 12:30 - 14:00 WIB)\n- **Jumat:** Pukul 08:00 - 16:45 WIB (Istirahat: 12:00 - 14:00 WIB)\n- **Sabtu & Minggu:** Libur (Tutup)\n\nPelayanan darurat Call Center 112 beroperasi selama 24 jam setiap hari.',1,4,'2026-09-04 07:47:12','2026-09-04 07:47:12'),(5,'general','Prosedur Magang & PKL Mahasiswa','magang, pkl, kerja praktik, magang mahasiswa, syarat magang, pengajuan magang, magang di kominfo, pkl di kominfo, cara magang','Untuk permohonan Magang / Praktik Kerja Lapangan (PKL) di Diskominfotik Kota Banda Aceh:\n\n1. Pemohon mengajukan **Surat Pengantar Resmi** dari Kampus / Sekolah yang ditujukan kepada Kepala Dinas Kominfotik Kota Banda Aceh.\n2. Menyertakan proposal magang / curriculum vitae singkat dan fotokopi KTM/KTP.\n3. Surat diserahkan ke bagian **Sekretariat (Gedung C Lantai 3 Balai Kota Banda Aceh)** atau dikirim via email: diskominfotik@bandaacehkota.go.id.\n4. Konfirmasi penerimaan dan penempatan bidang akan diberitahukan dalam 3-5 hari kerja.',1,5,'2026-09-04 07:47:12','2026-09-04 07:47:12'),(6,'general','Dasar Referensi & Sumber Informasi Resmi','referensi, sumber data, dari mana informasinya, apa referensinya, dasar hukum, keabsahan data, sumber rujukan, sumber informasi, referensi data','Seluruh informasi dan rincian yang disediakan asisten virtual ini bersumber dari dokumen resmi Standar Operasional Prosedur (SOP), Peraturan Walikota (Perwal), serta Direktori Pelayanan Kedinasan resmi Dinas Komunikasi, Informatika dan Statistik (Diskominfotik) Kota Banda Aceh yang terverifikasi.',1,6,'2026-09-04 09:55:03','2026-09-08 04:29:32');
