INSERT INTO `ekstraksi_job` VALUES (40,'selesai',0,100,100,'\nHALAMAN INI BERBENTUK FORMULIR SOP PEMERINTAH. Ikuti tambahan berikut.\n\nBAGIAN TABEL PROSEDUR (Uraian Prosedur / Langkah-langkah):\nHANYA UNTUK TABEL YANG MEMILIKI KOLOM \'Uraian Prosedur\', \'Pelaksana\', dan \'Mutu Baku\', gunakan format ini PERSIS untuk setiap langkah:\n- <Nomor>. <Uraian Prosedur>\n  - Pelaksana: <nama jabatan yang ada centang/simbol di kolomnya>\n  - Kelengkapan: <isi kolom Kelengkapan>\n  - Waktu: <isi kolom Waktu>\n  - Output: <isi kolom Output>\n\nATURAN TAMBAHAN:\n- Pelaksana ditentukan dari POSISI simbol flowchart (kotak/belah ketupat). Lihat simbol berada di bawah kolom jabatan mana.\n- Waktu dan Output adalah DUA kolom BERBEDA. JANGAN digabung. (Contoh BENAR: Waktu: 30 menit / Output: Disposisi).\n- Bila halaman ini TIDAK memuat kepala formulir (\'Nomor SOP\', \'Nama SOP\', \'Disahkan Oleh\'), JANGAN membuatnya. Halaman lanjutan memang tidak punya kepala; menuliskannya berarti mengarang.\n','Selesai! 1391 vektor berhasil disimpan ke korpus.','2026-09-03 04:17:06'),(41,'menunggu_koreksi',0,4,4,NULL,NULL,'2026-09-15 11:01:08'),(42,'selesai',0,100,100,NULL,'Selesai! 8 vektor berhasil disimpan ke korpus.','2026-09-21 03:59:00'),(44,'menunggu_koreksi',0,10,10,NULL,NULL,'2026-09-21 04:08:41');
